p='tools/tc.js'; s=open(p).read()
a='const F_UMB = `uniform vec3 col; uniform vec3 col2; uniform float op; uniform float tm; varying vec2 vUv; ${GN}\n  void main(){ float v=vUv.y; vec2 q=vec2(cos(vUv.x*6.2832),sin(vUv.x*6.2832)); float n=fbm(q*5.0+vec2(v*3.0-tm*1.2,0.0)); float fine=fbm(q*24.0+vec2(v*9.0-tm*2.0,3.0));\n    float sw=smoothstep(0.5,0.7,fbm(vec2(vUv.x*28.0+v*7.0-tm*0.8,v*3.0)));\n    vec3 c=mix(vec3(0.42,0.7,1.0),vec3(0.18,0.47,0.95),smoothstep(0.1,0.475,v)); c=mix(c,vec3(0.06,0.22,0.66),smoothstep(0.686,1.0,v)); c=mix(c,vec3(0.78,0.9,1.0),sw*0.4);\n    float rim=smoothstep(0.375,0.495,v+0.12*(fine-0.5))*(1.0-smoothstep(0.646,0.766,v+0.12*(n-0.5)));\n    float top=(1.0-smoothstep(0.0,0.12,v))*smoothstep(0.45,0.6,fine); c=mix(c,col2,max(rim,top));\n    float a=op*mix(0.82,1.0,rim)*(1.0-smoothstep(0.92,1.0,v)); if(a<0.02) discard; gl_FragColor=vec4(c,clamp(a,0.0,1.0)); }`;\n'
b='const F_UMB = `uniform vec3 col; uniform vec3 col2; uniform float op; uniform float tm; varying vec2 vUv; ${GN}\n  void main(){ float v=vUv.y; vec2 q=vec2(cos(vUv.x*6.2832),sin(vUv.x*6.2832)); float n=fbm(q*5.0+vec2(v*3.0-tm*1.2,0.0)); float fine=fbm(q*24.0+vec2(v*9.0-tm*2.0,3.0));\n    float sw=smoothstep(0.5,0.7,fbm(vec2(vUv.x*28.0+v*7.0-tm*0.8,v*3.0)));\n    vec3 c=mix(vec3(0.42,0.7,1.0),vec3(0.18,0.47,0.95),smoothstep(0.475,0.686,v)); c=mix(c,vec3(0.06,0.22,0.66),smoothstep(0.686,1.0,v)); c=mix(c,vec3(0.78,0.9,1.0),sw*0.4);\n    float lump=fbm(q*7.0+vec2(tm*0.4,1.0)); float rim=smoothstep(0.415,0.445,v+0.14*(lump-0.5)+0.03*(fine-0.5))*(1.0-smoothstep(0.646,0.766,v+0.12*(n-0.5)));\n    float top=(1.0-smoothstep(0.0,0.08,v))*smoothstep(0.5,0.6,fine); c=mix(c,col2,max(rim,top));\n    float a=op*mix(0.82,1.0,rim)*(1.0-smoothstep(0.92,1.0,v)); if(a<0.02) discard; gl_FragColor=vec4(c,clamp(a,0.0,1.0)); }`;\n'
assert a in s; s=s.replace(a,b); open(p,'w').write(s)
